/// In-place: add 4 to every element of the vector.
///
/// Safety note (per problem statement): all elements are <= 2_147_483_643,
/// so `+ 4` cannot overflow `i32`.
pub fn myfun2(x: &mut Vec<i32>) {
    for v in x.iter_mut() {
        *v += 4;
    }
}

